// Cloudflare Worker entry point for the JS deobfuscator.
//
// `pkg/` is generated by `wasm-pack build .. --target web` (see wrangler.toml's
// [build] step): `js_deobfuscator.js` is the wasm-bindgen glue, exporting the
// `init` function and the `deobfuscate_js(source, filename)` binding from
// src/lib.rs. The `.wasm` import resolves to a `WebAssembly.Module` that Wrangler
// bundles; `init` instantiates it.

import init, { deobfuscate_js } from "./pkg/js_deobfuscator.js";
import wasmModule from "./pkg/js_deobfuscator_bg.wasm";

// Instantiate once per isolate, at module load (top-level await).
await init(wasmModule);

const CORS = {
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "POST, GET, OPTIONS",
  "access-control-allow-headers": "content-type",
};

export default {
  async fetch(request) {
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: CORS });
    }

    if (request.method === "GET") {
      const usage =
        "js-deobfuscator — POST JavaScript source to get it deobfuscated.\n\n" +
        "  curl -X POST --data-binary @obfuscated.js https://worker.devirt.dev\n\n" +
        "Optional ?filename=foo.ts steers source-type inference (module/jsx/ts).\n";
      return new Response(usage, {
        headers: { "content-type": "text/plain; charset=utf-8", ...CORS },
      });
    }

    if (request.method !== "POST") {
      return new Response("Method Not Allowed\n", { status: 405, headers: CORS });
    }

    const source = await request.text();
    if (!source) {
      return new Response("Empty request body\n", { status: 400, headers: CORS });
    }

    const filename = new URL(request.url).searchParams.get("filename") || "input.js";

    try {
      const out = deobfuscate_js(source, filename);
      return new Response(out, {
        headers: { "content-type": "text/javascript; charset=utf-8", ...CORS },
      });
    } catch (err) {
      // A WASM trap surfaces here as a RuntimeError — most likely Boa's
      // `i32::MIN % -1` panic, which `panic = abort` can't contain (see ../README
      // "Constraints to know"). Fail this one request rather than hang. Note: the
      // isolate's wasm memory may be left poisoned after a trap; eliminate the
      // risk entirely by pinning a patched Boa (`wrapping_rem`) in ../Cargo.toml.
      const msg = (err && err.message) || String(err);
      return new Response("deobfuscation failed: " + msg + "\n", {
        status: 500,
        headers: CORS,
      });
    }
  },
};
